def solve_final(T, M):
    max_min_dist = 0
    for g in range(1, M + 1):
        for j in range(0, T // M + 1):
            s = j * M
            s_prime = (j + 1) * g
            if s < T < s_prime:
                # Check if the gap actually exists
                # The gap (jM, (j+1)g) exists if j(M-g) < g-1
                # Wait, j(M-g) < g-1 is only if M > g.
                # If M = g, then s = jM, s_prime = (j+1)M, gap is M.
                # If M = g, the gap (jM, (j+1)M) always exists.
                if M == g or j * (M - g) < g - 1:
                    dist = min(T - s, s_prime - T)
                    if dist > max_min_dist:
                        max_min_dist = dist
    return max_min_dist

print(solve_final(1810, 100))

